def f(blocks: List[List[str]]):
    '''
    blocks: a list of blocks, where each block is a list of strings
    '''
    def get_value(s: str, stack: List[str], var: Dict[str, str]) -> int:
        # Function to evaluate the expression
        idx = 0
        while idx < len(s):
            if s[idx] =='':
                idx += 1
                continue
            elif s[idx] == '+':
                stack.append(int(get_value(s[idx + 1:], stack, var)))
                idx += 1
            elif s[idx] == '-':
                stack.append(-int(get_value(s[idx + 1:], stack, var)))
                idx += 1
            elif s[idx] == '^':
                a = stack.pop()
                b = stack.pop()
                stack.append(a ** b)
                idx += 1
            elif s[idx] == '(':
                stack.append('(')
                idx += 1
            elif s[idx] == ')':
                idx += 1
                while stack[-1]!= '(':
                    stack.append(int(stack.pop()))
                stack.pop()
            else:
                while idx < len(s) and s[idx].isdigit():
                    idx += 1
                stack.append(int(s[:idx]))
                idx = len(s)
        return sum(stack)

    def calculate(s: str) -> int:
        # Function to calculate value
        var = {}
        stack = []
        i = 0
        while i < len(s):
            if s[i] =='':
                i += 1
                continue
            elif s[i].isalpha():
                var[s[i]] = str(get_value(s[i + 1:], stack, var))
                i += len(s[i])
            else:
                stack.append(int(s[i]))
                i += 1
        return get_value(s, stack, var)

    result = 0
    for block in blocks:
        for line in block:
            if line == '.':
                break
            result += calculate(line)
    return result
